// XEN push - generated by tools/make_upload.py. Paste into the Chrome DevTools console on the Perchance EDITOR page
// (top frame; logged in; the generator open for editing). It RUNS IMMEDIATELY - one paste, no further steps in the
// happy path. (__xenPush.cancel() aborts before the save is triggered.)
//
// Pipeline:
//   1. Installs a fetch hook FIRST, so no /api/save can slip through unpatched while the push is in flight.
//   2. Uploads each changed file to user.uploads.dev through upload.perchance.org (the same anonymous upload
//      protocol Perchance's own upload plugin uses; the editor's own iframe is reused), sha256 round-trip each one.
//   3. Finds and clicks the editor's Save button (best-effort DOM heuristic). The hook rewrites ONLY the srcManifest
//      (and model/template text if they changed) inside that one POST /api/save, after checking the live manifest
//      still matches the baseline. Your credentials stay inside the editor's own request; this script never reads,
//      stores or prints them. If no Save button can be found/enabled it prints ONE manual instruction and stays armed.
//   4. Verifies against the server twice (cache-busted), purges the server-rendered page cache, BLOCKS later saves from
//      this tab (its panel still holds the OLD file contents and would revert the server), then reloads the tab with the
//      "leave this page?" prompt silenced (everything is already on the server).
//   If a file was edited on Perchance since the baseline, nothing is patched and the save is BLOCKED (never sent).
(() => {
  const PLAN = /*PLAN*/null;
  if (window.__xenPush && window.__xenPush.installed) return console.warn("[xen] already installed - reload the page to reinstall.");
  const UPLOAD_ORIGIN = "https://upload.perchance.org";
  const KEY_RE = /\/file\/([0-9a-f]{32}\.[a-z0-9]{1,20})$/;
  const MIMES = {
    js: ["text/javascript", "application/javascript", "application/x-javascript"],
    mjs: ["text/javascript", "application/javascript"],
    json: ["application/json", "text/json"],
    txt: ["text/plain"],
    css: ["text/css"],
    svg: ["image/svg+xml"],
    webp: ["image/webp"],
    jpg: ["image/jpeg"],
    jpeg: ["image/jpeg"],
    png: ["image/png"],
    html: ["text/html"],
  };
  const state = { uploaded: {}, armed: false, locked: false, done: false, cancelled: false, started: false, clicks: 0, saveSeen: false, fallback: false, failed: false };
  const b64ToBytes = (b64) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  const hex = (buf) => [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
  const sha256 = async (bytes) => hex(await crypto.subtle.digest("SHA-256", bytes));
  const blobToDataUrl = (blob) => new Promise((res) => { const r = new FileReader(); r.onloadend = () => res(r.result); r.readAsDataURL(blob); });
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const log = (m) => console.log("%c[xen] " + m, "color:#06c");
  const bad = (m) => console.error("%c[xen] " + m, "color:#c00;font-weight:bold");

  // ---- upload iframe (same protocol as perchance.org/upload-plugin, anonymous mode) ----
  let iframe = null, readyPromise = null;
  // Prefer the editor's OWN upload iframe (it is the channel the editor uses for src files); only create one as a fallback.
  const findUploadIframes = (root, acc) => {
    for (const f of root.querySelectorAll("iframe")) { try { if ((f.src || "").startsWith(UPLOAD_ORIGIN)) acc.push(f); } catch (e) {} }
    for (const el of root.querySelectorAll("*")) if (el.shadowRoot) findUploadIframes(el.shadowRoot, acc);
    return acc;
  };
  const ensureIframe = () => readyPromise || (readyPromise = new Promise((resolve, reject) => {
    const existing = findUploadIframes(document, [])[0];
    if (existing) { iframe = existing; log("using the editor's own upload iframe"); return resolve(); }
    iframe = document.createElement("iframe");
    iframe.src = UPLOAD_ORIGIN + "/embed#" + JSON.stringify({ email: false, sessionToken: false });
    iframe.style.cssText = "width:1px;height:1px;border:none;position:fixed;top:-100px;left:-100px;";
    const onMsg = (e) => {
      if (e.source === iframe.contentWindow && e.origin === UPLOAD_ORIGIN && e.data && e.data.type === "uploadEmbedIsReady") {
        window.removeEventListener("message", onMsg); clearTimeout(readyTimer); resolve();
      }
    };
    window.addEventListener("message", onMsg);
    document.body.appendChild(iframe);
    const readyTimer = setTimeout(() => {
      // Never ready (upload.perchance.org slow or stalled): drop this iframe and the cached promise, so the next retry builds a fresh one
      // instead of re-reading the same rejection.
      window.removeEventListener("message", onMsg);
      const dead = iframe;
      iframe = null; readyPromise = null;
      try { dead.remove(); } catch (e) { console.warn("[xen] could not remove a stalled upload iframe:", e); }
      const origins = [...document.querySelectorAll("iframe")].map((f) => { try { return new URL(f.src || "about:blank", location.href).origin; } catch (e) { return "?"; } });
      reject(new Error("the upload iframe never became ready. Frames on this page: " + JSON.stringify(origins)));
    }, cfg.readyTimeoutMs);
  }));

  async function uploadOnce(bytes, mime) {
    await ensureIframe();
    const frame = iframe; // this upload's own channel: a later retry may replace the shared one
    const dataUrl = await blobToDataUrl(new Blob([bytes], { type: mime }));
    const requestId = "xenpush-" + Math.random().toString(36).slice(2);
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => { window.removeEventListener("message", h); reject(new Error("upload timed out")); }, cfg.uploadTimeoutMs);
      const h = (e) => {
        if (e.source !== frame.contentWindow || e.origin !== UPLOAD_ORIGIN) return;
        const d = e.data;
        if (d && d.type === "anonUploadResponse" && d.requestId === requestId) {
          clearTimeout(timer); window.removeEventListener("message", h);
          if (d.result && d.result.error) reject(new Error("upload error: " + d.result.error));
          else resolve({ url: String(d.result.url), size: d.result.size });
        }
      };
      window.addEventListener("message", h);
      frame.contentWindow.postMessage({ type: "anonUploadRequest", requestId, dataUrl, generatorName: PLAN.generator }, UPLOAD_ORIGIN);
    });
  }

  // Perchance's upload iframe sometimes stalls (its own fetch dies with "signal timed out" and it never answers). An
  // upload is an anonymous blob that nothing references until the save, so retrying is always safe.
  // Round-trip check: download what was just uploaded and compare hashes. The CDN sometimes answers with an error page
  // (HTTP 5xx such as Cloudflare's 525) — that is retried, never mistaken for a different file.
  async function downloadVerified(url, f) {
    let last = "";
    for (let attempt = 1; ; attempt++) {
      try {
        const res = await origFetch(url, { cache: "no-store" });
        if (res.ok === false) last = "HTTP " + res.status;
        else if ((await sha256(new Uint8Array(await res.arrayBuffer()))) === f.sha256) return;
        else last = "the downloaded copy differs from what was uploaded";
      } catch (e) { last = String((e && e.message) || e); }
      if (attempt >= cfg.uploadAttempts || state.cancelled) throw new Error("could not verify " + f.path + ": " + last + " (after " + attempt + " attempts)");
      console.warn("[xen] verify download " + attempt + "/" + cfg.uploadAttempts + " of " + f.path + " failed (" + last + ") - retrying");
      await sleep(cfg.retryDelayMs * attempt);
    }
  }
  // Perchance's upload iframe takes ONE upload at a time: an overlapping request is refused with
  // "another_upload_in_progress". So the upload step itself is queued behind a lock; only the work around it (hashing,
  // the download-and-verify round trip) runs for several files at once.
  let uploadLock = Promise.resolve();
  function uploadBytes(bytes, mime) {
    const run = uploadLock.then(() => uploadBytesNow(bytes, mime));
    uploadLock = run.catch(() => {});
    return run;
  }
  async function uploadBytesNow(bytes, mime) {
    // After a timeout the iframe is usually still busy with the stalled upload and refuses new ones ("another_upload_in_progress")
    // until that upload dies by itself. That is waiting, not failing: poll patiently without spending the attempt budget.
    let busyWaits = 0;
    for (let attempt = 1; ; attempt++) {
      try { return await uploadOnce(bytes, mime); }
      catch (e) {
        if (/another_upload_in_progress/.test(String((e && e.message) || e)) && busyWaits < cfg.busyWaitMax && !state.cancelled) {
          busyWaits++; attempt--;
          console.warn("[xen] the upload iframe is still busy with the previous upload; waiting " + Math.round(cfg.busyWaitMs / 1000) + " s (" + busyWaits + "/" + cfg.busyWaitMax + ")");
          await sleep(cfg.busyWaitMs);
          continue;
        }
        if (attempt >= cfg.uploadAttempts || state.cancelled) throw new Error((e.message || e) + " (after " + attempt + " attempts)");
        console.warn("[xen] upload attempt " + attempt + "/" + cfg.uploadAttempts + " failed (" + (e.message || e) + ") - retrying");
        await sleep(cfg.retryDelayMs * attempt);
      }
    }
  }

  // The server picks the stored extension from the MIME type; find one that yields the extension the manifest uses.
  const mimeCache = {}; // ext -> promise, so parallel uploads of one type probe only once
  const pickMime = (ext) => mimeCache[ext] || (mimeCache[ext] = probeMime(ext));
  async function probeMime(ext) {
    const cands = MIMES[ext] || [];
    for (let i = 0; i < cands.length; i++) {
      const probe = new TextEncoder().encode(`/* xen probe ${Math.random()} ${i} */`);
      const r = await uploadBytes(probe, cands[i]);
      const m = r.url.match(KEY_RE);
      if (m && m[1].endsWith("." + ext)) return cands[i];
    }
    throw new Error("no MIME type produced a ." + ext + " file; candidates were: " + cands.join(", "));
  }

  const origFetch = window.fetch;

  // ---- manifest patching (pure, testable) ----
  // The editor's save request carries the file manifest at the TOP LEVEL (body.srcManifest), usually only the entries that
  // changed (the server merges); generator.srcManifest is a (usually empty) copy inside the generator object.
  async function patchSaveBody(bodyStr) {
    const body = JSON.parse(bodyStr);
    const g = body.generator;
    if (!g || g.name !== PLAN.generator) throw new Error("save is for a different generator: " + (g && g.name));
    const isObj = (x) => x && typeof x === "object" && !Array.isArray(x);
    const top = isObj(body.srcManifest) ? body.srcManifest : null;
    const inner = isObj(g.srcManifest) ? g.srcManifest : null;
    const n = (x) => (x ? Object.keys(x).length : 0);
    // Structure report (key NAMES and counts only - never values, so no credentials can appear here).
    const sample = top && top[PLAN.editedPath] ? Object.keys(top[PLAN.editedPath]) : null;
    log("save request structure: " + JSON.stringify({ bodyKeys: Object.keys(body), topManifestEntries: top ? n(top) : null,
      topFirstPaths: top ? Object.keys(top).slice(0, 5) : null, topEntryFields: sample, innerManifestEntries: inner ? n(inner) : null, baselineEntries: PLAN.baselineManifestCount }));
    const target = top && n(top) >= n(inner) ? top : inner;
    if (!target || (n(target) === 0)) throw new Error("could not find the editor's manifest in the save request - paste the 'save request structure' line to Claude");
    const full = n(target) >= PLAN.baselineManifestCount * 0.8;
    if (full) {
      // "Changed on Perchance" is judged against the SERVER's manifest. The editor's own copy is a local draft that a blocked or
      // aborted earlier run leaves holding that run's upload keys, which is not an edit made on Perchance.
      const server = await serverManifest();
      for (const f of PLAN.files) {
        if (f.kind !== "src" || f.path === PLAN.editedPath) continue;
        const src = server || target;
        const cur = src[f.path] ? src[f.path].key : null;
        if (cur !== (f.expectKey || null)) throw new Error(`"${f.path}" changed on Perchance since the baseline (live key ${cur}, expected ${f.expectKey}). Pull + compare first.`);
      }
    } else {
      // changes-only manifest: the server merges it, so adding our entries is enough. A deletion cannot be expressed in
      // it, so deleted files become ONE manual step after the push (listed in the final message), never a guess.
      state.manualDeletes = PLAN.files.filter((f) => f.kind === "src" && f.deleted).map((f) => f.path);
      log("editor sent a changes-only manifest (" + n(target) + " entries): adding ours"
        + (state.manualDeletes.length ? "; " + state.manualDeletes.length + " deletion(s) left for you to do by hand" : ""));
    }
    for (const f of PLAN.files) {
      if (f.kind === "model" || f.kind === "template") {
        const field = f.kind === "model" ? "modelText" : "outputTemplate";
        const live = await sha256(new TextEncoder().encode(g[field] || ""));
        if (live !== f.baselineSha) throw new Error(`${field} changed on Perchance since the baseline. Pull + compare first.`);
        if (!f.deleted) g[field] = new TextDecoder().decode(b64ToBytes(f.b64));
      } else if (f.deleted) {
        if (full) delete target[f.path];
      } else {
        const u = state.uploaded[f.path];
        if (!u) throw new Error("not uploaded yet: " + f.path);
        const template = (top && top[PLAN.editedPath]) || {};
        const entry = Object.assign({}, template, target[f.path] || {}, { key: u.key, size: u.size });
        target[f.path] = entry;
      }
    }
    return JSON.stringify(body);
  }

  // ---- fetch hook: patches exactly one /api/save, then BLOCKS further saves from this (now stale) tab ----
  const cfg = Object.assign({ verifyDelayMs: 3000, verify2DelayMs: 2000, reloadDelayMs: 6000, saveTimeoutMs: 8000,
    uploadTimeoutMs: 90000, busyWaitMs: 10000, busyWaitMax: 18, readyTimeoutMs: 60000, uploadAttempts: 4, retryDelayMs: 3000, uploadConcurrency: 3,
    navigate: (u) => { location.href = u; } }, window.__xenPushCfg || {});
  // Perchance serves a CACHED server-rendered copy of the generator page (the editor boots from it). After a push that copy is
  // stale, and saving from it would write the old file list back. Ask the server to purge it (the same endpoint the page itself uses).
  async function purgeCache() {
    try {
      const q = "generatorName=" + encodeURIComponent(PLAN.generator) + "&importedGeneratorNames=" + encodeURIComponent((state.imports || []).join(","))
        + "&clientHtmlServerRenderTime=0&transferSize=1&queryParamString=&__cacheBust=" + Math.random();
      const r = await (await origFetch("/api/clearCacheIfGeneratorOrImportsHaveBeenUpdated?" + q, { cache: "no-store" })).json();
      log("cache purge requested; server said: " + JSON.stringify(r));
    } catch (e) { console.warn("[xen] cache purge failed (continuing): " + (e.message || e)); }
  }
  // The manifest the server holds right now (null when it cannot be read: the caller then falls back to the editor's copy).
  async function serverManifest() {
    try {
      const txt = await (await origFetch("/api/downloadGenerator?generatorName=" + encodeURIComponent(PLAN.generator), { cache: "no-store" })).text();
      const line = txt.split("\n").find((l) => l.startsWith('<script id="preloaded-generator-data"'));
      const man = JSON.parse(line.slice(line.indexOf(">") + 1, line.lastIndexOf("</script>"))).srcManifest;
      return man && typeof man === "object" && Object.keys(man).length ? man : null;
    } catch (e) { console.warn("[xen] could not read the server's manifest, checking the editor's copy: " + (e.message || e)); return null; }
  }
  // Returns true (ok), false (server does not have our files) or undefined (could not check).
  async function verify() {
    try {
      const txt = await (await origFetch("/api/downloadGenerator?generatorName=" + encodeURIComponent(PLAN.generator), { cache: "no-store" })).text();
      const line = txt.split("\n").find((l) => l.startsWith('<script id="preloaded-generator-data"'));
      const json = JSON.parse(line.slice(line.indexOf(">") + 1, line.lastIndexOf("</script>")));
      const man = json.srcManifest || {};
      const bad = Object.keys(state.uploaded).filter((p) => !man[p] || man[p].key !== state.uploaded[p].key);
      state.imports = Array.isArray(json.imports) ? json.imports : [];
      if (bad.length) { state.verified = false; console.error("[xen] VERIFY FAILED - Perchance does not have our versions of: " + bad.join(", ")); return false; }
      state.verified = true;
      log("VERIFIED on Perchance's server: " + Object.keys(state.uploaded).length + " files match (" + Object.keys(man).length + " manifest entries total)");
      return true;
    } catch (e) { console.warn("[xen] could not verify automatically: " + (e.message || e)); return undefined; }
  }
  // The editor asks "leave this page?" while it thinks there are unsaved changes. The server already holds everything
  // (verified), so the prompt is only noise for our own reload: silence it (capture listener runs before the editor's).
  // The editor keeps a LOCAL DRAFT of its file list (srcState, in IndexedDB) that still holds the old file keys and would
  // keep the files marked "modified" after a reload. resetToSaved() is the editor's own "drop the local draft" call; it
  // never saves anything. Best effort: a failure is logged and the reload still happens.
  async function discardEditorDraft() {
    try {
      if (window.srcState && typeof window.srcState.resetToSaved === "function") {
        await window.srcState.resetToSaved();
        log("cleared the editor's local file draft (dirty now: " + (typeof window.srcState.isDirty === "function" ? window.srcState.isDirty() : "?") + ")");
      }
    } catch (e) { console.warn("[xen] could not clear the editor's local draft: " + (e && e.message ? e.message : e)); }
  }
  function suppressLeavePrompt() {
    try { window.onbeforeunload = null; } catch (e) {}
    try { window.addEventListener("beforeunload", (e) => { e.stopImmediatePropagation(); }, true); } catch (e) {}
  }
  window.fetch = async function (input, init) {
    let path = "";
    try { path = new URL(typeof input === "string" ? input : input.url, location.href).pathname; } catch (e) {}
    if (state.locked && path === "/api/save") {
      console.error("[xen] BLOCKED a save from this tab: it still holds the OLD file list and would undo the upload. Reload the editor.");
      return new Response(JSON.stringify({ status: "blocked" }), { status: 409, headers: { "content-type": "application/json" } });
    }
    if (state.armed && path === "/api/save" && init && typeof init.body === "string") {
      state.armed = false;
      state.saveSeen = true;
      let sent = init, patched = false;
      try { sent = Object.assign({}, init, { body: await patchSaveBody(init.body) }); patched = true; log("patched /api/save manifest"); }
      catch (e) {
        // NEVER let an unpatched save through: the editor's file list may be stale, and saving it would overwrite the server.
        state.locked = true;
        console.error("NOT patched - this save was BLOCKED (nothing was sent). Reason: " + (e.message || e));
        return new Response(JSON.stringify({ status: "blocked" }), { status: 409, headers: { "content-type": "application/json" } });
      }
      const res = await origFetch.call(this, input, sent);
      res.clone().json().then(async (j) => {
        state.done = !!(patched && j && j.status === "saved");
        if (!state.done) return log("save response: " + JSON.stringify(j));
        state.locked = true; // the editor still holds the OLD file contents until it reloads: any save from it would revert the server
        log("OK saved (saveCount " + j.saveCount + "). Saves from this tab are blocked until it reloads.");
        await sleep(cfg.verifyDelayMs);
        const v1 = await verify();
        await purgeCache();
        await sleep(cfg.verify2DelayMs);
        const v2 = await verify();
        if (v1 === false || v2 === false) {
          state.locked = true; // only on failure: do not let this tab write its (wrong) file list over the server
          bad("PUSH FAILED - the server does not have our files. Saves from this tab are now blocked. Run pull + compare, then push again.");
          return;
        }
        if (v1 === undefined && v2 === undefined) console.warn("[xen] could not verify automatically - check the editor file list");
        log("PUSHED - verified on the server. Reloading this tab in " + Math.round(cfg.reloadDelayMs / 1000) + "s so the editor shows the new files (its panel still holds the old contents until then).");
        if (state.manualDeletes && state.manualDeletes.length) {
          console.warn("[xen] ONE MANUAL STEP after the reload: delete these files in the editor's file panel, then press Save:\n  - " + state.manualDeletes.join("\n  - "));
        }
        await discardEditorDraft();
        suppressLeavePrompt();
        setTimeout(() => cfg.navigate(location.pathname + "?__cacheBust=" + Math.random().toString(36).slice(2) + location.hash), cfg.reloadDelayMs);
      }).catch(() => {});
      return res;
    }
    return origFetch.apply(this, arguments);
  };

  // ---- Save-button trigger (best-effort DOM heuristic; degrades to ONE manual step) ----
  const SAVE_SEL = "button, input[type=button], input[type=submit], [role=button]";
  const WIDE_SEL = "a, div, span, li, i, img, svg, label, [onclick], [title], [aria-label], [id], [class]";
  const SAVE_WORD = /\bsave\b|\bsaving\b|\bguardar\b/i;
  const labelOf = (el) => [el.innerText, el.value, el.textContent, el.title, el.getAttribute && el.getAttribute("aria-label"), el.id].filter((x) => typeof x === "string").join(" ").trim();
  // Documents to search: the top one plus every same-origin iframe (cross-origin ones throw and are skipped).
  const docsToSearch = () => {
    const docs = [document];
    try { for (const f of document.querySelectorAll("iframe")) { try { if (f.contentDocument) docs.push(f.contentDocument); } catch (e) {} } } catch (e) {}
    return docs;
  };
  const findSaveButtons = (root, acc, sel) => {
    for (const el of root.querySelectorAll(sel || SAVE_SEL)) {
      try {
        const t = (el.innerText || el.value || el.textContent || "").trim();
        if (/^save$/i.test(t)) acc.push(el);
        else if (sel && t.length < 40 && SAVE_WORD.test(labelOf(el)) && !acc.includes(el)) acc.push(el);
      } catch (e) {}
    }
    for (const el of root.querySelectorAll("*")) if (el.shadowRoot) findSaveButtons(el.shadowRoot, acc, sel);
    return acc;
  };
  // Last resort: what Save-looking things exist at all? Printed automatically (tag/id/class/short label only - no values).
  const describeSaveCandidates = () => {
    const out = [];
    for (const d of docsToSearch()) {
      try {
        for (const el of d.querySelectorAll(WIDE_SEL)) {
          try { const l = labelOf(el); if (l.length < 60 && SAVE_WORD.test(l)) out.push(el.tagName.toLowerCase() + (el.id ? "#" + el.id : "") + (el.className && typeof el.className === "string" ? "." + el.className.trim().split(/\s+/).join(".") : "") + " [" + l.replace(/\s+/g, " ") + "]" + (el.disabled ? " DISABLED" : "")); } catch (e) {}
        }
      } catch (e) {}
    }
    return out.slice(0, 12);
  };
  const pressCtrlS = () => {
    const targets = [document.activeElement, document, window].filter(Boolean);
    for (const t of targets) {
      for (const type of ["keydown", "keyup"]) {
        try { t.dispatchEvent(new KeyboardEvent(type, { key: "s", code: "KeyS", keyCode: 83, which: 83, ctrlKey: true, bubbles: true, cancelable: true })); } catch (e) {}
      }
    }
  };
  // Try a net-zero edit (insert + delete one char) in the most plausible editor surface to make the editor "dirty"
  // in case Save is disabled while there are no unsaved changes. Best effort; the fallback covers failure.
  async function makeEditorDirty() {
    const cands = [];
    for (const sel of ["textarea", "input[type=text]", "[contenteditable=true]", ".cm-content"]) {
      try { document.querySelectorAll(sel).forEach((el) => cands.push(el)); } catch (e) {}
    }
    for (const el of cands) {
      try {
        el.focus();
        if (el.selectionStart != null && el.setSelectionRange) { const n = el.value.length; el.setSelectionRange(n, n); }
        if (document.execCommand && document.execCommand("insertText", false, " ")) {
          document.execCommand("delete", false, null);
          log("made the editor dirty with a net-zero edit");
          return true;
        }
      } catch (e) {}
    }
    return false;
  }
  async function waitSave(timeoutMs) {
    const t0 = Date.now();
    while (Date.now() - t0 < timeoutMs) {
      if (state.saveSeen || state.locked || state.done) return true;
      await sleep(100);
    }
    return false;
  }
  // Perchance's own Save control: <div data-ref="saveButton" onclick="app.saveGenerator();"> (label "saved" while clean).
  async function triggerPerchanceSave(timeoutMs) {
    const el = document.querySelector('[data-ref="saveButton"]');
    if (!el) return false;
    const attempt = async (how, fn) => {
      try { fn(); } catch (e) { console.warn("[xen] " + how + " threw: " + (e.message || e)); return false; }
      return waitSave(timeoutMs);
    };
    state.clicks++;
    // saveGenerator() returns early while saveState is "saved" (nothing changed). The editor's own menu bar owns that flag.
    try {
      if (typeof menuBar !== "undefined" && menuBar && typeof menuBar.setSaveState === "function") { menuBar.setSaveState("unsaved"); log("marked the editor as having unsaved changes"); }
    } catch (e) { console.warn("[xen] could not mark unsaved: " + (e.message || e)); }
    log("found Perchance's Save button; clicking it");
    if (await attempt("click", () => el.click())) return true;
    if (await makeEditorDirty() && await attempt("click after edit", () => el.click())) return true;
    if (window.app && typeof window.app.saveGenerator === "function") {
      log("calling app.saveGenerator() directly");
      if (await attempt("app.saveGenerator", () => window.app.saveGenerator())) return true;
      try { log("saveGenerator source (first 700 chars): " + String(window.app.saveGenerator).slice(0, 700)); } catch (e) {}
    }
    return false;
  }
  async function triggerSave(timeoutMs) {
    if (await triggerPerchanceSave(timeoutMs)) return { clicked: true };
    const enabled = (sel) => docsToSearch().flatMap((d) => findSaveButtons(d, [], sel)).filter((b) => !b.disabled);
    let btns = enabled();
    if (!btns.length) { if (await makeEditorDirty()) btns = enabled(); }
    if (!btns.length) btns = enabled(WIDE_SEL);
    if (btns.length) {
      if (btns.length > 1) log("found " + btns.length + " Save-like elements; clicking the first enabled one");
      state.clicks++;
      try { btns[0].click(); } catch (e) { return { clicked: false, reason: "click threw: " + (e.message || e) }; }
      if (await waitSave(timeoutMs)) return { clicked: true };
    }
    // No clickable Save control worked: press Ctrl+S, the editor's keyboard shortcut.
    if (typeof KeyboardEvent === "function") {
      log("no Save control worked; pressing Ctrl+S");
      pressCtrlS();
      if (await waitSave(timeoutMs)) return { clicked: true };
    }
    const seen = describeSaveCandidates();
    log("Save-like elements on the page: " + (seen.length ? JSON.stringify(seen) : "none"));
    return { clicked: false, reason: btns.length ? "clicked Save but no /api/save request appeared" : "no Save control found in the editor DOM" };
  }

  // ---- runner (auto-started on paste) ----
  const finished = new Promise((res) => { state._finish = res; });
  function finish() { if (state._finish) { const f = state._finish; state._finish = null; f(); } }
  async function run() {
    try {
      const toUpload = PLAN.files.filter((f) => f.kind === "src" && !f.deleted);
      const nDel = PLAN.files.filter((f) => f.deleted).length;
      log("plan: " + PLAN.files.length + " file(s) - " + toUpload.length + " to upload, " + PLAN.files.filter((f) => f.kind !== "src" && !f.deleted).length + " model/template, " + nDel + " delete(s)");
      console.table(PLAN.files.map((f) => ({ kind: f.kind, path: f.path, change: f.deleted ? "DELETE" : (f.expectKey || f.kind !== "src" ? "MODIFY" : "NEW"), bytes: f.size })));
      log("(1/3) uploading " + toUpload.length + " file(s) (one upload at a time; verifying up to " + cfg.uploadConcurrency + " in parallel)...");
      // A few files in the pipeline at once: uploads queue behind the iframe's lock (uploadBytes), while verifying one
      // file overlaps with uploading the next. The first failure stops new files; the ones already running finish, then
      // the push fails as a whole. Nothing is saved before all are in.
      let next = 0, done = 0, firstError = null;
      const uploadFile = async (f) => {
        const bytes = b64ToBytes(f.b64);
        if ((await sha256(bytes)) !== f.sha256) throw new Error("embedded copy is corrupted: " + f.path);
        const mime = await pickMime(f.expectExt);
        const r = await uploadBytes(bytes, mime);
        const m = r.url.match(KEY_RE);
        if (!m || !m[1].endsWith("." + f.expectExt)) throw new Error("unexpected upload url for " + f.path + ": " + r.url);
        await downloadVerified(r.url, f);
        state.uploaded[f.path] = { key: m[1], size: bytes.length };
        log("  " + (++done) + "/" + toUpload.length + " uploaded + verified " + f.path + " -> " + m[1]);
      };
      const worker = async () => {
        while (!firstError && !state.cancelled && next < toUpload.length) {
          try { await uploadFile(toUpload[next++]); } catch (e) { firstError = firstError || e; }
        }
      };
      await Promise.all(Array.from({ length: Math.max(1, Math.min(cfg.uploadConcurrency, toUpload.length)) }, worker));
      if (firstError) throw firstError;
      if (state.cancelled) return cancelled();
      state.armed = true;
      log("(2/3) triggering editor save...");
      const t = await triggerSave(cfg.saveTimeoutMs);
      if (!t.clicked) {
        console.warn("[xen] COULD NOT CLICK SAVE (" + t.reason + ")");
        console.warn("[xen] MANUAL STEP: add a space at the end of src/" + PLAN.editedPath + " in the editor, then press Save. The push is armed and will patch that save.");
        state.fallback = true;
      } else {
        log("(3/3) save request sent - the script patches, verifies twice and reloads from here on");
      }
    } catch (e) {
      state.failed = true;
      bad("PUSH FAILED - nothing was saved to your generator. Reason: " + (e.message || e));
    } finally {
      finish();
    }
  }
  function cancelled() { state.armed = false; log("cancelled - nothing further will happen; reload the editor to discard the hook."); }

  const api = {
    installed: true,
    finished,
    run() { if (state.started) return; state.started = true; return run(); },
    cfg,
    verify,
    cancel() { state.cancelled = true; state.armed = false; },
    state,
    _patch: patchSaveBody,
  };
  window.__xenPush = api;
  api.run(); // one paste - it goes by itself
})();
